function compareSemver(a: string, b: string): -1 | 0 | 1 {
  function parse(version: string): { major: number; minor: number; patch: number; pre: string[] | null } {
    // Strip build metadata
    const buildIdx = version.indexOf('+');
    if (buildIdx !== -1) {
      version = version.slice(0, buildIdx);
    }

    const preIdx = version.indexOf('-');
    let coreStr: string;
    let preStr: string | null = null;

    if (preIdx !== -1) {
      coreStr = version.slice(0, preIdx);
      preStr = version.slice(preIdx + 1);
    } else {
      coreStr = version;
    }

    const coreParts = coreStr.split('.');
    if (coreParts.length !== 3) {
      throw new Error(`Invalid semver: "${version}"`);
    }

    const [majorStr, minorStr, patchStr] = coreParts;

    function parseNumeric(s: string, field: string): number {
      if (!/^\d+$/.test(s)) {
        throw new Error(`Invalid semver ${field}: "${s}"`);
      }
      if (s.length > 1 && s[0] === '0') {
        throw new Error(`Invalid semver ${field} has leading zero: "${s}"`);
      }
      return Number(s);
    }

    const major = parseNumeric(majorStr, 'major');
    const minor = parseNumeric(minorStr, 'minor');
    const patch = parseNumeric(patchStr, 'patch');

    let pre: string[] | null = null;
    if (preStr !== null) {
      if (preStr.length === 0) {
        throw new Error(`Invalid semver pre-release: empty`);
      }
      pre = preStr.split('.');
      for (const id of pre) {
        if (id.length === 0) {
          throw new Error(`Invalid semver pre-release identifier: empty`);
        }
        if (/^\d+$/.test(id)) {
          // Numeric: no leading zeros
          if (id.length > 1 && id[0] === '0') {
            throw new Error(`Invalid semver pre-release numeric identifier has leading zero: "${id}"`);
          }
        } else {
          // Alphanumeric: must only contain [0-9A-Za-z-]
          if (!/^[0-9A-Za-z-]+$/.test(id)) {
            throw new Error(`Invalid semver pre-release identifier: "${id}"`);
          }
        }
      }
    }

    return { major, minor, patch, pre };
  }

  const pa = parse(a);
  const pb = parse(b);

  function cmp(x: number, y: number): -1 | 0 | 1 {
    return x < y ? -1 : x > y ? 1 : 0;
  }

  const majorCmp = cmp(pa.major, pb.major);
  if (majorCmp !== 0) return majorCmp;

  const minorCmp = cmp(pa.minor, pb.minor);
  if (minorCmp !== 0) return minorCmp;

  const patchCmp = cmp(pa.patch, pb.patch);
  if (patchCmp !== 0) return patchCmp;

  // Pre-release precedence:
  // - Release (no pre) > pre-release
  if (pa.pre === null && pb.pre === null) return 0;
  if (pa.pre === null && pb.pre !== null) return 1;
  if (pa.pre !== null && pb.pre === null) return -1;

  const preA = pa.pre!;
  const preB = pb.pre!;
  const len = Math.min(preA.length, preB.length);

  for (let i = 0; i < len; i++) {
    const idA = preA[i];
    const idB = preB[i];

    const aIsNum = /^\d+$/.test(idA);
    const bIsNum = /^\d+$/.test(idB);

    if (aIsNum && bIsNum) {
      const r = cmp(Number(idA), Number(idB));
      if (r !== 0) return r;
    } else if (aIsNum && !bIsNum) {
      return -1;
    } else if (!aIsNum && bIsNum) {
      return 1;
    } else {
      // Both alphanumeric: compare lexically in ASCII order
      if (idA < idB) return -1;
      if (idA > idB) return 1;
    }
  }

  // All preceding identifiers equal: larger set wins
  return cmp(preA.length, preB.length);
}
