function buildOrder(deps: Record<string, string[]>): string[] {
  // Collect all packages
  const allPackages = new Set<string>();
  for (const [pkg, pkgDeps] of Object.entries(deps)) {
    allPackages.add(pkg);
    for (const d of pkgDeps) {
      allPackages.add(d);
    }
  }

  // Build adjacency list and in-degree map
  const inDegree = new Map<string, number>();
  const graph = new Map<string, string[]>();

  for (const pkg of allPackages) {
    inDegree.set(pkg, 0);
    graph.set(pkg, []);
  }

  for (const [pkg, pkgDeps] of Object.entries(deps)) {
    for (const d of pkgDeps) {
      graph.get(d)!.push(pkg);
      inDegree.set(pkg, inDegree.get(pkg)! + 1);
    }
  }

  // Topological sort using a min-heap (simulate with sorted array)
  // Use a priority queue (min-heap) for lexicographically smallest order
  const available: string[] = [];
  for (const [pkg, deg] of inDegree) {
    if (deg === 0) {
      available.push(pkg);
    }
  }
  available.sort();

  const result: string[] = [];

  while (available.length > 0) {
    // Pick lexicographically smallest
    const pkg = available.shift()!;
    result.push(pkg);

    const neighbors = graph.get(pkg) ?? [];
    const newAvailable: string[] = [];
    for (const neighbor of neighbors) {
      const newDeg = inDegree.get(neighbor)! - 1;
      inDegree.set(neighbor, newDeg);
      if (newDeg === 0) {
        newAvailable.push(neighbor);
      }
    }

    // Insert new available packages in sorted order
    if (newAvailable.length > 0) {
      newAvailable.sort();
      // Merge into available (which is already sorted)
      let i = 0, j = 0;
      const merged: string[] = [];
      while (i < available.length && j < newAvailable.length) {
        if (available[i] < newAvailable[j]) {
          merged.push(available[i++]);
        } else {
          merged.push(newAvailable[j++]);
        }
      }
      while (i < available.length) merged.push(available[i++]);
      while (j < newAvailable.length) merged.push(newAvailable[j++]);
      available.splice(0, available.length, ...merged);
    }
  }

  if (result.length !== allPackages.size) {
    throw new Error("cycle detected in dependency graph");
  }

  return result;
}
