function compareSemver(a: string, b: string): -1 | 0 | 1 {
  function parse(v: string): { major: number; minor: number; patch: number; pre: string[] | null } {
    // Strip build metadata
    const plusIdx = v.indexOf('+');
    if (plusIdx !== -1) v = v.slice(0, plusIdx);

    const preIdx = v.indexOf('-');
    let core: string;
    let preStr: string | null = null;
    if (preIdx !== -1) {
      core = v.slice(0, preIdx);
      preStr = v.slice(preIdx + 1);
    } else {
      core = v;
    }

    const parts = core.split('.');
    if (parts.length !== 3) throw new Error(`Invalid semver: "${v}"`);

    function parseNumeric(s: string, label: string): number {
      if (!/^\d+$/.test(s)) throw new Error(`Invalid ${label} in semver: "${s}"`);
      if (s.length > 1 && s[0] === '0') throw new Error(`Leading zero in ${label}: "${s}"`);
      return Number(s);
    }

    const major = parseNumeric(parts[0], 'major');
    const minor = parseNumeric(parts[1], 'minor');
    const patch = parseNumeric(parts[2], 'patch');

    let pre: string[] | null = null;
    if (preStr !== null) {
      if (preStr === '') throw new Error(`Empty pre-release in semver`);
      pre = preStr.split('.');
      for (const id of pre) {
        if (id === '') throw new Error(`Empty pre-release identifier in semver`);
        if (/^\d+$/.test(id)) {
          if (id.length > 1 && id[0] === '0') throw new Error(`Leading zero in pre-release identifier: "${id}"`);
        } else {
          if (!/^[0-9A-Za-z-]+$/.test(id)) throw new Error(`Invalid pre-release identifier: "${id}"`);
        }
      }
    }

    return { major, minor, patch, pre };
  }

  const pa = parse(a);
  const pb = parse(b);

  function cmp(x: number, y: number): -1 | 0 | 1 {
    return x < y ? -1 : x > y ? 1 : 0;
  }

  let r: -1 | 0 | 1;

  r = cmp(pa.major, pb.major);
  if (r !== 0) return r;

  r = cmp(pa.minor, pb.minor);
  if (r !== 0) return r;

  r = cmp(pa.patch, pb.patch);
  if (r !== 0) return r;

  // Pre-release comparison
  if (pa.pre === null && pb.pre === null) return 0;
  if (pa.pre === null && pb.pre !== null) return 1;
  if (pa.pre !== null && pb.pre === null) return -1;

  const preA = pa.pre!;
  const preB = pb.pre!;
  const len = Math.min(preA.length, preB.length);

  for (let i = 0; i < len; i++) {
    const idA = preA[i];
    const idB = preB[i];

    const numA = /^\d+$/.test(idA);
    const numB = /^\d+$/.test(idB);

    if (numA && numB) {
      r = cmp(Number(idA), Number(idB));
      if (r !== 0) return r;
    } else if (!numA && !numB) {
      if (idA < idB) return -1;
      if (idA > idB) return 1;
    } else {
      // numeric < alphanumeric
      return numA ? -1 : 1;
    }
  }

  if (preA.length < preB.length) return -1;
  if (preA.length > preB.length) return 1;
  return 0;
}
