function buildOrder(deps: Record<string, string[]>): string[] {
  // Collect all packages
  const allPackages = new Set<string>();
  for (const [pkg, pkgDeps] of Object.entries(deps)) {
    allPackages.add(pkg);
    for (const d of pkgDeps) {
      allPackages.add(d);
    }
  }

  // Build adjacency list and in-degree count
  // Edge: dependency -> dependent (dep must come before pkg)
  const graph = new Map<string, string[]>();
  const inDegree = new Map<string, number>();

  for (const pkg of allPackages) {
    if (!graph.has(pkg)) graph.set(pkg, []);
    if (!inDegree.has(pkg)) inDegree.set(pkg, 0);
  }

  for (const [pkg, pkgDeps] of Object.entries(deps)) {
    for (const d of pkgDeps) {
      graph.get(d)!.push(pkg);
      inDegree.set(pkg, (inDegree.get(pkg) ?? 0) + 1);
    }
  }

  // Kahn's algorithm with a min-heap (simulate with sorted array)
  // Use a sorted set for lexicographically smallest order
  const available: string[] = [];
  for (const [pkg, deg] of inDegree.entries()) {
    if (deg === 0) available.push(pkg);
  }
  available.sort();

  const result: string[] = [];

  while (available.length > 0) {
    // Take the lexicographically smallest
    const current = available.shift()!;
    result.push(current);

    const neighbors = graph.get(current) ?? [];
    const newlyAvailable: string[] = [];

    for (const neighbor of neighbors) {
      const newDeg = (inDegree.get(neighbor) ?? 0) - 1;
      inDegree.set(neighbor, newDeg);
      if (newDeg === 0) {
        newlyAvailable.push(neighbor);
      }
    }

    // Insert new available packages maintaining sorted order
    if (newlyAvailable.length > 0) {
      newlyAvailable.sort();
      // Merge into available (both sorted)
      let i = 0;
      for (const pkg of newlyAvailable) {
        while (i < available.length && available[i] < pkg) i++;
        available.splice(i, 0, pkg);
        i++;
      }
    }
  }

  if (result.length !== allPackages.size) {
    throw new Error("cycle detected in dependency graph");
  }

  return result;
}
